import java.util.jar.Manifest;

/**
 * Minimal stand-in for maven-jar-plugin:jar. Packages the build output
 * directory into {@code ${project.build.directory}/${project.build.finalName}.jar}
 * and attaches it as the project artifact so spring-boot:repackage can
 * find it.
 */
public class JarMojo extends AbstractMojo {

    private File classesDirectory;

    private File outputDirectory;

    private String finalName;

    private MavenProject project;

    @Override
    public void execute() throws MojoExecutionException {
        File jarFile = new File(outputDirectory, finalName + ".jar");
        getLog().info("Building jar: " + jarFile);
        try {
            Files.createDirectories(outputDirectory.toPath());
            Manifest manifest = new Manifest();
            manifest.getMainAttributes().put(Attributes.Name.MANIFEST_VERSION, "1.0");
            try (JarOutputStream jos = new JarOutputStream(new FileOutputStream(jarFile), manifest)) {
                Path base = classesDirectory.toPath();
                if (Files.isDirectory(base)) {
                    List<Path> entries;
                    try (var stream = Files.walk(base)) {
                        entries = stream.filter(Files::isRegularFile).sorted().toList();
                    }
                    for (Path p : entries) {
                        String name = base.relativize(p).toString().replace(File.separatorChar, '/');
                        jos.putNextEntry(new JarEntry(name));
                        Files.copy(p, jos);
                        jos.closeEntry();
                    }
                }
            }
        } catch (IOException | UncheckedIOException e) {
            throw new MojoExecutionException("Failed to create jar " + jarFile, e);
        }
        if (project != null && project.getArtifact() != null) {
            project.getArtifact().setFile(jarFile);
        }
    }
}
